/**
 * Growing past the chart's sectors by selecting (findings/builder_system_design.md §18, item 7):
 * hexes picked in an empty slot are generated by making the slot's sector first, then the
 * systems, as one act with one Undo. The server has no single call for both yet, so it is two
 * calls behind the seam (findings/builder_sector_ready.md), and the Undo is two calls too: the
 * systems are undone, then each new sector is deleted (the server keeps a copy, as every delete).
 * A sector is never made without its sixteen subsectors; none is made on its own.
 */
import { reactive } from 'vue';
import { buildStore, ownSectors, type OwnSector } from './seam.ts';
import { generateMany, selectOnMap } from './acts.ts';
import { cleanName, slotGroups, slotKeysToSectors } from './sectors.ts';
import { build } from './state.ts';

/** The names typed for the new sectors, by the slot's address; kept while the selection lasts. */
export const growUi = reactive({
    names: {} as Record<string, string>,
    /** The slot whose name is missing or too long, so the pane can put the cursor in its box. */
    want: '',
    /** Goes up each time the name box is asked for, so asking twice for the same slot still moves the cursor. */
    focus: 0,
    busy: false,
    error: '',
});

/** The hexes reach into an empty slot: Generate there needs the new sector's name first. */
export function inEmptySlot(keys: readonly string[]): boolean {
    return slotGroups(keys).length > 0;
}

/** Generate was asked for by key or menu on hexes in an empty slot: the pane's name box takes the cursor; nothing is made yet. */
export function askSectorName(keys: readonly string[]): void {
    const first = slotGroups(keys)[0];
    if (!first) return;
    growUi.want = first.slug;
    growUi.focus += 1;
}

/**
 * Make each slot's sector, then generate the empty hexes. A name that is missing stops the act
 * before anything is made, and says which. If a sector cannot be made, the ones made a moment
 * before are deleted again and nothing is generated.
 */
export async function generateGrowing(keys: readonly string[]): Promise<void> {
    const port = ownSectors();
    const store = buildStore();
    if (!port || !store || growUi.busy || build.job) return;
    const slots = slotGroups(keys);
    growUi.error = '';
    growUi.want = '';
    const names: Record<string, string> = {};
    for (const group of slots) {
        const name = cleanName(growUi.names[group.slug] ?? '');
        if (!name) {
            growUi.want = group.slug;
            growUi.focus += 1;
            growUi.error = slots.length === 1 ? 'Name the new sector first.' : 'Name each new sector first.';
            return;
        }
        names[group.slug] = name;
    }
    growUi.busy = true;
    const made: OwnSector[] = [];
    const ids: Record<string, string> = {};
    const takeBack = async (): Promise<void> => {
        for (const sector of [...made].reverse()) await port.remove(sector.id);
    };
    try {
        for (const group of slots) {
            const sector = await port.make(names[group.slug], group.slot);
            made.push(sector);
            ids[group.slug] = sector.id;
        }
    } catch (err) {
        growUi.error = (err instanceof Error && err.message ? err.message : 'The sector could not be made.') + (made.length ? ' The sectors made a moment before are taken back.' : ' Nothing was made.');
        await takeBack().catch(() => undefined);
        growUi.busy = false;
        return;
    }
    const real = slotKeysToSectors(keys, ids);
    growUi.names = {};
    growUi.busy = false;
    // The hexes now have their sector: the selection is theirs, then the systems are generated into it.
    selectOnMap(real);
    generateMany(real, { names: made.map((sector) => sector.name), undo: takeBack });
}
